// ============================================================
//  Osteoporosis Self-Assessment — Risk Score Calculator
//  Based on the Q007 Make.com blueprint.
//
//  13 yes/no questions.
//
//  Scoring logic:
//    Risk factors    (q2–q6, q8–q13): Yes = 1 point
//    Protective      (q1 exercise, q7 calcium): No = 1 point
//      (not exercising / not meeting calcium = a risk factor)
//
//  Tiers — mirroring the Q007 blueprint switch exactly:
//    risk score <= 3  → Result 1 (Lower risk)
//    risk score >  3  → Result 2 (Elevated risk)
// ============================================================

const data = $input.first().json.body || $input.first().json;

const fields = [
  { name: 'q1_exercise',          protective: true  },
  { name: 'q2_alcohol',           protective: false },
  { name: 'q3_inactive',          protective: false },
  { name: 'q4_smoke',             protective: false },
  { name: 'q5_caffeine',          protective: false },
  { name: 'q6_medication',        protective: false },
  { name: 'q7_calcium',           protective: true  },
  { name: 'q8_absent_periods',    protective: false },
  { name: 'q9_postmenopausal',    protective: false },
  { name: 'q10_low_testosterone', protective: false },
  { name: 'q11_ethnicity',        protective: false },
  { name: 'q12_family_history',   protective: false },
  { name: 'q13_curved_back',      protective: false }
];

let riskScore = 0;
const scores = {};
const warnings = [];

for (const field of fields) {
  const raw = data[field.name];
  const ans = raw ? String(raw).trim().toLowerCase() : 'no';
  let score = 0;
  if (field.protective) {
    score = (ans === 'no') ? 1 : 0; // not doing the protective thing = risk
  } else {
    score = (ans === 'yes') ? 1 : 0;
  }
  scores[field.name] = { raw, ans, score };
  riskScore += score;
  if (!raw) warnings.push(field.name + ' is missing');
}

// Two-tier result — matching Q007 blueprint switch exactly
let resultNum, resultLabel, resultContent;
if (riskScore <= 3) {
  resultNum = 1;
  resultLabel = 'Lower Risk Profile';
  resultContent = 'You have few identified risk factors for osteoporosis at this time. Maintaining your current protective habits — regular weight-bearing exercise, adequate calcium and vitamin D intake, and avoiding smoking and excess alcohol — will help preserve your bone health. A baseline bone density scan is a sensible proactive step, particularly if you are over 40.';
} else {
  resultNum = 2;
  resultLabel = 'Elevated Risk Profile';
  resultContent = 'You have identified multiple risk factors for osteoporosis. With four or more risk factors, your bone density may be significantly affected. Osteoporosis is highly manageable when detected early — we strongly recommend a DEXA bone density scan, a comprehensive hormone and bone health panel, and a consultation with one of our specialists to discuss your prevention and treatment options.';
}

return [{ json: {
  patientName:    data.first_name   || '',
  patientEmail:   data.email        || '',
  mailingList:    data.mailing_list || '',
  riskScore,
  resultNum,
  resultLabel,
  resultContent,
  _debug_scores:   scores,
  _debug_warnings: warnings
}}];

const d = $input.first().json;
// Escape only the dynamic name used in the HTML greeting.
function escapePatientName(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
const greeting = d.patientName ? ('Dear ' + escapePatientName(d.patientName)) : 'Hi there';
const year = new Date().getFullYear();

const introMap = {
  1: `Osteoporosis is a condition in which bones become fragile and brittle due to loss of bone mineral density. It affects over 200 million people worldwide and is responsible for more than 8.9 million fractures annually — yet the majority of people who have it don't know until a fracture occurs.<br/><br/>Based on your responses, your risk profile is relatively low, with fewer than four risk factors identified. This is a good position to be in. The best way to stay there is to maintain your current protective habits — regular weight-bearing exercise, adequate calcium and vitamin D intake, limiting alcohol and caffeine, and avoiding smoking.<br/><br/>We also recommend establishing a bone density baseline with a DEXA scan, especially if you are aged 40 or over. Knowing your bone mineral density today gives you a clear reference point for tracking any changes over time, and allows your clinician to intervene early if needed.`,
  2: `Osteoporosis is a progressive condition in which bone mineral density declines, making bones increasingly fragile and prone to fractures. It is often called the 'silent disease' because bone loss occurs without symptoms — until a fracture happens, often from a minor fall or movement that would not normally cause injury.<br/><br/>Based on your responses, you have four or more risk factors associated with reduced bone density. These may include postmenopausal status, low testosterone, physical inactivity, smoking, high alcohol or caffeine intake, long-term medication use, a family history of osteoporosis, or absence of menstrual periods — all clinically recognised contributors to bone loss.<br/><br/>The good news is that osteoporosis is highly manageable when detected early. Hormone replacement therapy (HRT) has strong clinical evidence for protecting and improving bone density — particularly oestrogen in women and testosterone in men. Combined with targeted nutritional support, exercise, and lifestyle changes, a comprehensive treatment plan can significantly slow or reverse bone loss.<br/><br/>The critical first step is knowing where your bone density actually stands today. A DEXA scan and hormone panel will give you and your clinician the information needed to build a personalised prevention or treatment plan.`
};

const introText = introMap[d.resultNum] || introMap[2];

const labTests = [
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/ZRTBloodSpotTestKit-9_1024x1024_2x_3025b07b-9b81-4d8f-85a4-2c9aff366530_1024x1024@2x.jpg?v=1571716034',
    title: 'Female Hormone Panel — At Home Test Kit',
    desc: 'Measures FSH, LH, oestradiol, and progesterone. Low oestrogen is a primary driver of bone loss in women, particularly after menopause. At-home blood spot collection.',
    price: '$179.00',
    url: 'https://store.hrt.org/products/female-hormone-panel-at-home-test-kit'
  },
